import React from 'react'
import Header from '../../components/Header';
import Input from '../../components/Input';

import {RegisterWrapper,BodyRegisterContainer, InputRegisterContainer,InputRegister} from './styles';

const Register = ()=>{
    return(
        <RegisterWrapper>
            <Header />

                <BodyRegisterContainer>
                 <InputRegisterContainer>
                   <InputRegister placeholder='title'/>
                 </InputRegisterContainer>

                </BodyRegisterContainer>
                </RegisterWrapper>
        
    )
}

export default Register
